"""Gemini wrapper (google-genai): tokens, cost, backoff, concurrency cap.

Tokens are MEASURED from usage metadata. Dollars are COMPUTED from the PRICES dict (list price).
Pricing is marked ASSUMED until verified.
"""
import asyncio
import json
import re
from dataclasses import dataclass, field

import config

PRICES = {
    "pricing_date": "UNVERIFIED",
    "pricing_source": "ASSUMED",
    "models": {
        "gemini-2.5-flash": {"input_per_m": 0.30, "output_per_m": 2.50},
    },
    "fallback": {"input_per_m": 0.30, "output_per_m": 2.50},
}

RETRYABLE_CODES = {429, 503}
MAX_RETRIES = 5


class LLMError(Exception):
    pass


def price_for(model: str) -> tuple[float, float, bool]:
    m = PRICES["models"].get(model)
    known = m is not None
    m = m or PRICES["fallback"]
    return m["input_per_m"], m["output_per_m"], known


def compute_cost(model: str, input_tokens: int, output_tokens: int) -> float:
    pin, pout, _ = price_for(model)
    return (input_tokens * pin + output_tokens * pout) / 1_000_000


@dataclass
class RunStats:
    """Accumulates tokens and cost by stage (plan, build, retry, autopsy)."""
    model: str = ""
    input_tokens: int = 0
    output_tokens: int = 0
    cost_usd: float = 0.0
    by_stage: dict = field(default_factory=dict)
    calls: int = 0

    def add(self, stage: str, input_tokens: int, output_tokens: int, cost: float):
        self.input_tokens += input_tokens
        self.output_tokens += output_tokens
        self.cost_usd += cost
        self.calls += 1
        s = self.by_stage.setdefault(stage, {"input_tokens": 0, "output_tokens": 0, "cost_usd": 0.0, "calls": 0})
        s["input_tokens"] += input_tokens
        s["output_tokens"] += output_tokens
        s["cost_usd"] += cost
        s["calls"] += 1

    @property
    def tokens(self) -> int:
        return self.input_tokens + self.output_tokens

    def cost_by_stage(self) -> dict:
        return {k: round(v["cost_usd"], 8) for k, v in self.by_stage.items()}


def parse_json(text: str):
    t = text.strip()
    t = re.sub(r"^```(?:json)?\s*|\s*```$", "", t, flags=re.S).strip()
    try:
        return json.loads(t)
    except json.JSONDecodeError:
        m = re.search(r"\{.*\}", t, flags=re.S)
        if m:
            try:
                return json.loads(m.group(0))
            except json.JSONDecodeError:
                pass
        raise LLMError(f"model did not return valid JSON: {t[:200]!r}")


class LLM:
    def __init__(self, model: str | None = None, client=None, temperature: float = 0.2,
                 concurrency: int = 2, sleep=asyncio.sleep):
        self.model = model or config.GEMINI_MODEL
        self.temperature = temperature
        self._client = client
        self._sem = asyncio.Semaphore(concurrency)
        self._sleep = sleep
        self.mock = False

    def _get_client(self):
        if self._client is None:
            if not config.GEMINI_API_KEY:
                raise LLMError("GEMINI_API_KEY is not set (copy .env.example to .env)")
            from google import genai
            self._client = genai.Client(api_key=config.GEMINI_API_KEY)
        return self._client

    async def _raw(self, system: str, user: str, json_mode: bool) -> tuple[str, int, int]:
        """One API call. Returns (text, input_tokens, output_tokens). Overridden by MockLLM."""
        from google.genai import types
        cfg = types.GenerateContentConfig(
            system_instruction=system,
            temperature=self.temperature,
            response_mime_type="application/json" if json_mode else None,
        )
        resp = await self._get_client().aio.models.generate_content(model=self.model, contents=user, config=cfg)
        u = resp.usage_metadata
        in_tok = int(getattr(u, "prompt_token_count", 0) or 0)
        # thinking tokens are billed as output
        out_tok = int(getattr(u, "candidates_token_count", 0) or 0) + int(getattr(u, "thoughts_token_count", 0) or 0)
        return (resp.text or ""), in_tok, out_tok

    async def _with_backoff(self, system, user, json_mode):
        delay = 1.0
        for attempt in range(MAX_RETRIES + 1):
            try:
                async with self._sem:
                    return await self._raw(system, user, json_mode)
            except Exception as e:  # noqa: BLE001
                code = getattr(e, "code", None) or getattr(e, "status_code", None)
                if code in RETRYABLE_CODES and attempt < MAX_RETRIES:
                    await self._sleep(delay)
                    delay *= 2
                    continue
                if isinstance(e, LLMError):
                    raise
                raise LLMError(f"Gemini call failed (code={code}): {e}") from e

    async def call(self, system: str, user: str, stage: str = "build", stats: RunStats | None = None) -> str:
        text, i, o = await self._with_backoff(system, user, json_mode=False)
        self._record(stats, stage, i, o)
        return text

    async def json_call(self, system: str, user: str, stage: str = "plan", stats: RunStats | None = None):
        text, i, o = await self._with_backoff(system, user, json_mode=True)
        self._record(stats, stage, i, o)
        return parse_json(text)

    def _record(self, stats, stage, i, o):
        if stats is not None:
            stats.model = self.model
            stats.add(stage, i, o, compute_cost(self.model, i, o))

"""Trust Rails: budget cap, attempt cap, wall-clock timeout, kill switch. Every rail that fires is logged."""
import time


class RailFired(Exception):
    def __init__(self, rail: str, detail: str = ""):
        super().__init__(f"{rail}: {detail}")
        self.rail = rail
        self.detail = detail


class Rails:
    def __init__(self, budget_usd: float, max_attempts: int, timeout_s: float):
        self.budget_usd = budget_usd
        self.max_attempts = max_attempts
        self.timeout_s = timeout_s
        self.killed = False
        self.fired: list[dict] = []
        self._t0 = time.monotonic()

    def fire(self, rail: str, detail: str = "") -> dict:
        rec = {"rail": rail, "detail": detail, "t": round(time.monotonic() - self._t0, 2)}
        self.fired.append(rec)
        return rec

    def kill(self):
        self.killed = True

    def check_kill(self):
        if self.killed:
            raise RailFired("kill_switch", "stopped by operator")

    def check_budget(self, stats):
        if stats.cost_usd >= self.budget_usd:
            raise RailFired("budget", f"spent ${stats.cost_usd:.6f} of ${self.budget_usd:.6f} cap")

    def check_time(self):
        if time.monotonic() - self._t0 >= self.timeout_s:
            raise RailFired("timeout", f"exceeded {self.timeout_s}s wall clock")

    def summary(self) -> dict:
        return {
            "budget_usd": self.budget_usd,
            "max_attempts": self.max_attempts,
            "timeout_s": self.timeout_s,
            "sandbox": "network blocked, 15s check timeout, generated code only ever opened in headless Chromium",
            "approval_gate": "human approval required before a build is marked Approved",
            "fired": self.fired,
        }

"""Run folders. Generated code is HTML/JS only and is never executed in Python."""
import datetime
import json
import secrets
from pathlib import Path

import config


def new_run_id() -> str:
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d-%H%M%S") + "-" + secrets.token_hex(2)


def run_dir(run_id: str, runs_dir=None) -> Path:
    d = Path(runs_dir or config.RUNS) / run_id
    d.mkdir(parents=True, exist_ok=True)
    return d


def write(run_id: str, name: str, content: str, runs_dir=None) -> Path:
    p = run_dir(run_id, runs_dir) / name
    p.write_text(content, encoding="utf-8")
    return p


def write_json(run_id: str, name: str, obj, runs_dir=None) -> Path:
    return write(run_id, name, json.dumps(obj, indent=2, default=str), runs_dir)

"""Acceptance checks. Pass/fail is decided here, in code, never by an LLM.

Sync Playwright runs in a worker thread (asyncio.to_thread). Network is blocked, everything except file://
is aborted, and the whole check is wrapped in a hard 15 second timeout.
"""
import asyncio
import re
from dataclasses import dataclass, field
from pathlib import Path

import config

STORAGE_RE = re.compile(r"\b(localStorage|sessionStorage)\b")
ACTION_TIMEOUT_MS = 5_000


@dataclass
class Result:
    passed: bool
    test: str = ""
    expected: str = ""
    actual: str = ""
    console_errors: list = field(default_factory=list)

    def as_dict(self) -> dict:
        """Keys match RETRY_USER placeholders."""
        return {
            "test_name": self.test,
            "expected": self.expected,
            "actual": self.actual,
            "console_errors": "; ".join(self.console_errors) or "none",
        }


class _Fail(Exception):
    def __init__(self, test, expected, actual):
        self.test, self.expected, self.actual = test, expected, actual


def _set(page, sel, val):
    page.evaluate(
        "([s, v]) => { const e = document.querySelector(s); if (!e) throw new Error('missing ' + s); "
        "e.value = v; e.dispatchEvent(new Event('input', {bubbles: true})); "
        "e.dispatchEvent(new Event('change', {bubbles: true})); }",
        [sel, str(val)],
    )


def _click(page, sel):
    page.click(sel)
    page.wait_for_timeout(60)


def _text(page, sel) -> str:
    return page.inner_text(sel).strip()


def _err_visible(page) -> bool:
    return page.is_visible("#error") and bool(_text(page, "#error"))


# ---- T1 Tip Splitter ---------------------------------------------------------------------------------
def _tip_case(page, url, bill, people, tip):
    page.goto(url)
    _set(page, "#bill", bill)
    _set(page, "#people", people)
    _set(page, "#tip", tip)
    _click(page, "#calc")


def _expect_invalid(page, url, test, bill, people, tip):
    _tip_case(page, url, bill, people, tip)
    visible, res = _err_visible(page), _text(page, "#result")
    if not visible or res:
        raise _Fail(test, "#error visible with a message and #result empty",
                    f"#error visible={visible}, #result={res!r}")


def check_tip_splitter(page, url):
    _tip_case(page, url, 100, 4, 20)
    got = _text(page, "#result")
    if "30.00" not in got:
        raise _Fail("split_basic", "#result contains 30.00 (bill 100, 4 people, 20% tip)", f"#result={got!r}")
    _expect_invalid(page, url, "zero_people", 100, 0, 20)
    _expect_invalid(page, url, "negative_tip", 100, 4, -5)
    _expect_invalid(page, url, "blank_bill", "", 4, 10)
    _expect_invalid(page, url, "non_numeric_bill", "abc", 4, 10)


# ---- T2 Habit Tracker --------------------------------------------------------------------------------
def check_habit_tracker(page, url):
    page.goto(url)
    for name in ("Read", "Walk"):
        _set(page, "#habit-input", name)
        _click(page, "#add")
    n = page.locator(".habit").count()
    if n != 2:
        raise _Fail("add_two_habits", ".habit count is 2 after adding Read and Walk", f"count={n}")
    btn = page.locator(".habit .done-btn")
    (btn.first if btn.count() else page.locator(".done-btn").first).click()
    page.wait_for_timeout(60)
    streak = _text(page, "#streak")
    if "1" not in streak:
        raise _Fail("streak_after_done", "#streak shows 1 after marking one habit done", f"#streak={streak!r}")
    _set(page, "#habit-input", "")
    _click(page, "#add")
    n = page.locator(".habit").count()
    if n != 2:
        raise _Fail("empty_add_rejected", ".habit count stays 2 when adding an empty habit", f"count={n}")


# ---- T3 Flashcards -----------------------------------------------------------------------------------
def check_flashcards(page, url):
    page.goto(url)
    for f, b in (("Q1", "A1"), ("Q2", "A2")):
        _set(page, "#front", f)
        _set(page, "#back", b)
        _click(page, "#add-card")
    before = _text(page, "#card-view")
    _click(page, "#next")
    after = _text(page, "#card-view")
    if before == after:
        raise _Fail("next_changes_card", "#card-view changes after #next", f"before={before!r}, after={after!r}")
    _click(page, "#flip")
    flipped = _text(page, "#card-view")
    if not any(a in flipped for a in ("A1", "A2")):
        raise _Fail("flip_shows_back", "#card-view shows the back text (A1 or A2) after #flip", f"#card-view={flipped!r}")


TEMPLATE_CHECKS = {
    "tip_splitter": check_tip_splitter,
    "habit_tracker": check_habit_tracker,
    "flashcards": check_flashcards,
}


def _run_sync(template_name: str, path) -> Result:
    html = Path(path).read_text(encoding="utf-8", errors="ignore")
    if STORAGE_RE.search(html):
        return Result(False, "no_browser_storage", "no localStorage or sessionStorage usage",
                      "the HTML references localStorage or sessionStorage")
    errors: list[str] = []
    try:
        from playwright.sync_api import sync_playwright
        with sync_playwright() as p:
            browser = p.chromium.launch(headless=True)
            try:
                ctx = browser.new_context(offline=True)
                ctx.route("**/*", lambda r: r.continue_() if r.request.url.startswith("file://") else r.abort())
                page = ctx.new_page()
                page.set_default_timeout(ACTION_TIMEOUT_MS)
                page.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
                page.on("pageerror", lambda e: errors.append(str(e)))
                TEMPLATE_CHECKS[template_name](page, Path(path).resolve().as_uri())
            finally:
                browser.close()
    except _Fail as f:
        return Result(False, f.test, f.expected, f.actual, errors)
    except Exception as e:  # noqa: BLE001
        return Result(False, "check_error", "the check completes", f"{type(e).__name__}: {str(e)[:300]}", errors)
    return Result(True, console_errors=errors)


async def run(template, path, timeout_s: float | None = None) -> Result:
    """`template` is a Template (or a template name). Hard timeout around the whole check."""
    name = getattr(template, "name", template)
    limit = timeout_s or config.CHECK_TIMEOUT_S
    try:
        return await asyncio.wait_for(asyncio.to_thread(_run_sync, name, path), timeout=limit)
    except asyncio.TimeoutError:
        return Result(False, "timeout", f"check finishes within {limit}s", f"check exceeded {limit}s")

"""MOCK LLM for tests and offline UI development ONLY.

Runs that use it are labelled mock=true and are excluded from every metric. The mock's first baseline
attempt is deliberately buggy so the failure -> diagnose -> fix path can be exercised in tests.
It must never be used in experiments (experiments/ab.py refuses it).
"""
import json
from pathlib import Path

from agent.llm import LLM

FIX = Path(__file__).resolve().parent.parent / "tests" / "fixtures"


def _tok(s: str) -> int:
    return max(1, len(s) // 4)


class MockLLM(LLM):
    def __init__(self, **kw):
        super().__init__(model="mock-model", **kw)
        self.mock = True

    async def _raw(self, system, user, json_mode):
        if "Founder step" in system:
            text = json.dumps({
                "template": "tip_splitter", "product_name": "SplitEasy",
                "one_line_pitch": "Split any bill in two taps.", "target_user": "friends dining out",
                "adaptation_note": "none (MOCK)",
            })
        elif "Flight Recorder" in system:
            text = json.dumps({
                "failed_span": "acceptance_check",
                "root_cause": "The code divides by the people count without checking it is greater than zero. (MOCK)",
                "evidence": ["check expected #error visible", "generated code computes bill / people directly"],
                "recommended_prompt_change": "Validate every numeric input and show a message in #error before dividing.",
                "confidence": "medium",
            })
        elif "generalizes the common lesson" in system:
            text = json.dumps({"patch": "Validate all numeric inputs (zero, negative, blank, non-numeric) and show a message in #error."})
        else:
            good = "previous attempt failed" in user or "edge cases" in system
            html = (FIX / ("good_tip.html" if good else "bad_tip.html")).read_text(encoding="utf-8")
            text = f"I used plain DOM scripting. (MOCK)\n```html\n{html}\n```"
        return text, _tok(system + user), _tok(text)

